import type { BoardFocus } from '../board/Board.tsx';
import type { TournamentPhase, TournamentRecord, TournamentState } from './model.ts';
import type { RefObject } from 'react';
import './tournament.css';

export interface TournamentPlayHandle {
  exportTournament(): string;
}

interface TournamentPlayProps {
  initial: TournamentState;
  ref: RefObject<TournamentPlayHandle | null>;
  onPhaseChange(phase: TournamentPhase): void;
  onFinished(record: TournamentRecord): void;
  onBack(): void;
}

export function TournamentPlay({ initial, ref, onPhaseChange, onFinished, onBack }: TournamentPlayProps) {
  const [tournament, setTournament] = useState(initial);
  const current = useRef(tournament);
  const board = useRef<BoardFocus>(null);
  const action = useRef<HTMLButtonElement>(null);
  const backButton = useRef<HTMLButtonElement>(null);
  const previousPhase = useRef<TournamentPhase | null>(null);

  function commit(next: TournamentState): void {
    const previous = current.current;
    if (next === previous) return;
    current.current = next;
    setTournament(next);
    if (next.phase !== previous.phase) onPhaseChange(next.phase);
    if (previous.phase !== 'finished' && next.phase === 'finished')
      onFinished(tournamentRecord(next));
  }

  const clock = useGameClock(tournament, current, commit, tickTournament);
  useLayoutEffect(() => {
    const previous = previousPhase.current;
    if (previous === null) {
      if (tournament.phase === 'ready') action.current?.focus();
      if (tournament.phase === 'finished') backButton.current?.focus();
    } else if (previous !== tournament.phase) {
      if (previous === 'ready' && tournament.phase === 'playing') board.current?.focusRemembered();
      else if (tournament.phase === 'finished') backButton.current?.focus();
      else if (tournament.phase !== 'playing') action.current?.focus();
    }
    previousPhase.current = tournament.phase;
  }, [tournament.phase]);
  useImperativeHandle(
    ref,
    () => ({
      exportTournament() {
        clock.synchronize();
        return encodeTournament(current.current);
      },
    }),
    [clock.synchronize],
  );

  const round = tournament.rounds[tournament.currentRound];
  const match = round?.matches[tournament.currentMatch];
  if (!round || !match) return <p className="tournament-message">Tournament bracket unavailable.</p>;
  const displayTurn = tournament.phase === 'nextTurn' ? 1 : tournament.currentTurn;
  const playerSeed = match.players[displayTurn];
  const player = tournament.players.find((candidate) => candidate.seed === playerSeed);
  const champion = tournament.players.find(
    (candidate) => candidate.seed === tournament.championSeed,
  );
  const showsGame = tournament.phase !== 'ready' && tournament.phase !== 'finished';

  return (
    <div className="tournament-play">
      {tournament.phase !== 'finished' && (
        <>
          <p className="tournament-round-label">Round: {round.name}</p>
          <p className="tournament-current-player" role="status" aria-live="polite" aria-atomic="true">
            <span key={`${tournament.currentRound}-${tournament.currentMatch}-${displayTurn}`}>
              Now playing: {player?.name ?? 'Pending'}
            </span>
          </p>
        </>
      )}
      <Bracket players={tournament.players} rounds={tournament.rounds} />
      {showsGame && (
        <>
          <TournamentStatus game={tournament.game} />
          <p id="tournament-board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <Board
            key={tournament.generation}
            game={tournament.game}
            activate={(index) => {
              clock.synchronize();
              commit(finishTournamentTurn(current.current, index, Date.now()));
            }}
            ref={board}
          />
        </>
      )}
      {tournament.phase === 'ready' && (
        <button
          ref={action}
          type="button"
          className="control tournament-action"
          onClick={() => commit(startTournamentTurn(current.current))}
        >
          Start turn
        </button>
      )}
      {tournament.phase === 'nextTurn' && (
        <button
          ref={action}
          type="button"
          className="control tournament-action"
          onClick={() => commit(advanceTournamentTurn(current.current))}
        >
          Next turn
        </button>
      )}
      {tournament.phase === 'nextMatch' && (
        <button
          ref={action}
          type="button"
          className="control tournament-action"
          onClick={() => commit(advanceTournamentMatch(current.current))}
        >
          Next match
        </button>
      )}
      {tournament.phase === 'finished' && champion && (
        <section className="tournament-champion" aria-live="polite">
          <p>Champion: {champion.name}</p>
          <button ref={backButton} type="button" className="control" onClick={onBack}>
            Back to game
          </button>
        </section>
      )}
    </div>
  );
}

import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import type { TournamentResult, TournamentState } from './model.ts';
import { winningSeed } from './scoring.ts';

export function startTournamentTurn(tournament: TournamentState): TournamentState {
  return tournament.phase === 'ready'
    ? { ...tournament, phase: 'playing', paused: false }
    : tournament;
}

export function tickTournament(
  tournament: TournamentState,
  generation: number,
  milliseconds: number,
): TournamentState {
  if (tournament.generation !== generation || tournament.paused) return tournament;
  const game = advanceGame(tournament.game, milliseconds);
  return game === tournament.game ? tournament : { ...tournament, game };
}

export function finishTournamentTurn(
  tournament: TournamentState,
  index: number,
  completedAtMs: number,
): TournamentState {
  if (tournament.phase !== 'playing') return tournament;
  const game = activateCard(tournament.game, index);
  if (game === tournament.game) return tournament;
  if (!isWon(game)) return { ...tournament, game };
  const rounds = [...tournament.rounds];
  const round = rounds[tournament.currentRound];
  const match = round?.matches[tournament.currentMatch];
  if (!round || !match) return tournament;
  const result = { moves: game.moves, elapsedMs: game.elapsedMs };
  const results: readonly [TournamentResult | null, TournamentResult | null] =
    tournament.currentTurn === 0 ? [result, match.results[1]] : [match.results[0], result];
  if (tournament.currentTurn === 0) {
    const matches = [...round.matches];
    matches[tournament.currentMatch] = { ...match, results };
    rounds[tournament.currentRound] = { ...round, matches };
    return { ...tournament, rounds, game, phase: 'nextTurn', paused: true };
  }
  const [firstSeed, secondSeed] = match.players;
  const [firstResult, secondResult] = results;
  if (firstSeed === null || secondSeed === null || !firstResult || !secondResult) return tournament;
  const winnerSeed = winningSeed(firstSeed, firstResult, secondSeed, secondResult);
  const matches = [...round.matches];
  matches[tournament.currentMatch] = { ...match, results, winnerSeed };
  rounds[tournament.currentRound] = { ...round, matches };
  if (tournament.currentRound + 1 < rounds.length) {
    const nextRound = rounds[tournament.currentRound + 1];
    const nextMatches = [...(nextRound?.matches ?? [])];
    const nextMatchIndex = Math.floor(tournament.currentMatch / 2);
    const target = nextMatches[nextMatchIndex];
    if (nextRound && target) {
      const nextPlayers: readonly [number | null, number | null] =
        tournament.currentMatch % 2 === 0
          ? [winnerSeed, target.players[1]]
          : [target.players[0], winnerSeed];
      nextMatches[nextMatchIndex] = { ...target, players: nextPlayers };
      rounds[tournament.currentRound + 1] = { ...nextRound, matches: nextMatches };
    }
  }
  const finalMatch = tournament.currentRound === rounds.length - 1;
  return {
    ...tournament,
    rounds,
    game,
    championSeed: finalMatch ? winnerSeed : null,
    completedAtMs: finalMatch ? completedAtMs : null,
    phase: finalMatch ? 'finished' : 'nextMatch',
    paused: true,
  };
}

export function advanceTournamentTurn(tournament: TournamentState): TournamentState {
  if (tournament.phase !== 'nextTurn') return tournament;
  const match = tournament.rounds[tournament.currentRound]?.matches[tournament.currentMatch];
  if (!match) return tournament;
  return {
    ...tournament,
    currentTurn: 1,
    phase: 'ready',
    game: createGame(match.boardCode),
    generation: tournament.generation + 1,
    paused: true,
  };
}

export function advanceTournamentMatch(tournament: TournamentState): TournamentState {
  if (tournament.phase !== 'nextMatch') return tournament;
  let currentRound = tournament.currentRound;
  let currentMatch = tournament.currentMatch + 1;
  const currentRoundLength = tournament.rounds[currentRound]?.matches.length;
  if (currentRoundLength === undefined) return tournament;
  if (currentMatch >= currentRoundLength) {
    currentRound += 1;
    currentMatch = 0;
  }
  const match = tournament.rounds[currentRound]?.matches[currentMatch];
  if (!match || match.players[0] === null || match.players[1] === null) return tournament;
  return {
    ...tournament,
    currentRound,
    currentMatch,
    currentTurn: 0,
    phase: 'ready',
    game: createGame(match.boardCode),
    generation: tournament.generation + 1,
    paused: true,
  };
}
import { decodeSnapshot } from '../snapshot.ts';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { readTournamentPlayers, readTournamentRounds } from './validation.ts';
import type { GameState } from '../game.ts';
import type { TournamentPhase, TournamentState } from './model.ts';

function isTournamentPhase(value: unknown): value is TournamentPhase {
  return (
    value === 'ready' ||
    value === 'playing' ||
    value === 'nextTurn' ||
    value === 'nextMatch'
  );
}

function isInitialGame(game: GameState): boolean {
  return (
    !game.started &&
    game.moves === 0 &&
    game.elapsedMs === 0 &&
    game.matched.length === 0 &&
    game.selection.kind === SelectionKind.closed
  );
}

function matchesEarlierRounds(
  rounds: NonNullable<ReturnType<typeof readTournamentRounds>>,
  currentRound: number,
  currentMatch: number,
): boolean {
  return rounds.every((round, roundIndex) =>
    round.matches.every((match, matchIndex) => {
      const finished = roundIndex < currentRound || (roundIndex === currentRound && matchIndex < currentMatch);
      const future = roundIndex > currentRound || (roundIndex === currentRound && matchIndex > currentMatch);
      if (finished) return match.winnerSeed !== null;
      if (future) return match.winnerSeed === null && match.results[0] === null && match.results[1] === null;
      return true;
    }),
  );
}

export function readActiveTournament(value: unknown): TournamentState | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, [
      'version',
      'status',
      'startedAtMs',
      'players',
      'rounds',
      'current',
      'gameSnapshot',
    ]) ||
    value.version !== 1 ||
    value.status !== 'active' ||
    !isNonnegativeSafeInteger(value.startedAtMs) ||
    typeof value.gameSnapshot !== 'string' ||
    !isJsonObject(value.current) ||
    !hasExactKeys(value.current, ['roundIndex', 'matchIndex', 'turnIndex', 'phase'])
  )
    return null;
  const players = readTournamentPlayers(value.players);
  if (!players) return null;
  const playerCount = players.length === 4 ? 4 : 8;
  const rounds = readTournamentRounds(value.rounds, playerCount);
  const game = decodeSnapshot(value.gameSnapshot);
  const currentRound = value.current.roundIndex;
  const currentMatch = value.current.matchIndex;
  const currentTurn = value.current.turnIndex;
  const phase = value.current.phase;
  if (
    !rounds ||
    !game ||
    !isNonnegativeSafeInteger(currentRound) ||
    !isNonnegativeSafeInteger(currentMatch) ||
    (currentTurn !== 0 && currentTurn !== 1) ||
    !isTournamentPhase(phase) ||
    currentRound >= rounds.length ||
    currentMatch >= (rounds[currentRound]?.matches.length ?? 0) ||
    !matchesEarlierRounds(rounds, currentRound, currentMatch)
  )
    return null;
  const match = rounds[currentRound]?.matches[currentMatch];
  const playerSeed = match?.players[currentTurn];
  if (!match || playerSeed === null || playerSeed === undefined || game.boardCode !== match.boardCode)
    return null;
  const firstResult = match.results[0];
  const secondResult = match.results[1];
  const currentResult = currentTurn === 0 ? firstResult : secondResult;
  if (currentTurn === 1 && firstResult === null) return null;
  if (phase === 'ready') {
    if (currentResult !== null || (currentTurn === 1 && firstResult === null) || !isInitialGame(game))
      return null;
  } else if (phase === 'playing') {
    if (currentResult !== null || isWon(game)) return null;
  } else if (phase === 'nextTurn') {
    if (
      currentTurn !== 0 ||
      firstResult === null ||
      secondResult !== null ||
      match.winnerSeed !== null ||
      game.matched.length !== game.deck.length ||
      firstResult.moves !== game.moves ||
      Math.floor(firstResult.elapsedMs) !== Math.floor(game.elapsedMs)
    )
      return null;
  } else if (
    currentTurn !== 1 ||
    firstResult === null ||
    secondResult === null ||
    match.winnerSeed === null ||
    game.matched.length !== game.deck.length ||
    secondResult.moves !== game.moves ||
    Math.floor(secondResult.elapsedMs) !== Math.floor(game.elapsedMs)
  ) {
    return null;
  }
  return {
    startedAtMs: value.startedAtMs,
    completedAtMs: null,
    players,
    rounds,
    currentRound,
    currentMatch,
    currentTurn,
    phase,
    championSeed: null,
    game,
    generation: 0,
    paused: phase !== 'playing',
  };
}

import { parseBoardCode } from '../deck.ts';
import { createGame } from '../game.ts';
import type { TournamentMatch, TournamentState } from './model.ts';

interface RoundSpec {
  readonly name: 'Quarterfinal' | 'Semifinal' | 'Final';
  readonly size: number;
  readonly matchCount: number;
}

const MATCHUPS: Readonly<Record<4 | 8, readonly (readonly [number, number])[]>> = {
  4: [
    [1, 4],
    [2, 3],
  ],
  8: [
    [1, 8],
    [4, 5],
    [3, 6],
    [2, 7],
  ],
};

function roundSpecs(playerCount: 4 | 8): readonly RoundSpec[] {
  return playerCount === 4
    ? [
        { name: 'Semifinal', size: 6, matchCount: 2 },
        { name: 'Final', size: 8, matchCount: 1 },
      ]
    : [
        { name: 'Quarterfinal', size: 4, matchCount: 4 },
        { name: 'Semifinal', size: 6, matchCount: 2 },
        { name: 'Final', size: 8, matchCount: 1 },
      ];
}

export function tournamentRoundPlan(playerCount: 4 | 8): readonly RoundSpec[] {
  return roundSpecs(playerCount);
}

export function openingPairings(
  playerCount: 4 | 8,
): readonly (readonly [number, number])[] {
  return MATCHUPS[playerCount];
}

export function tournamentBoardSizes(playerCount: 4 | 8): readonly number[] {
  return roundSpecs(playerCount).flatMap(({ size, matchCount }) =>
    Array.from({ length: matchCount }, () => size),
  );
}

export function normalizePlayerName(value: string): string {
  return value.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function validatePlayerNames(
  drafts: readonly string[],
  playerCount: 4 | 8,
): { readonly valid: true; readonly names: readonly string[] } | { readonly valid: false; readonly message: string } {
  const names = Array.from({ length: playerCount }, (_, index) =>
    normalizePlayerName(drafts[index] ?? ''),
  );
  if (names.some((name) => [...name].length < 2 || [...name].length > 20))
    return { valid: false, message: 'Use 2 to 20 characters.' };
  if (new Set(names.map((name) => name.toLowerCase())).size !== names.length)
    return { valid: false, message: 'Each name must be different.' };
  return { valid: true, names };
}

function emptyMatch(boardCode: string, players: readonly [number | null, number | null]): TournamentMatch {
  return { boardCode, players, results: [null, null], winnerSeed: null };
}

export function createTournament(
  names: readonly string[],
  boardCodes: readonly string[],
  startedAtMs: number,
): TournamentState {
  if (
    (names.length !== 4 && names.length !== 8) ||
    !Number.isSafeInteger(startedAtMs) ||
    startedAtMs < 0
  )
    throw new Error('Invalid tournament setup.');
  const playerCount = names.length === 4 ? 4 : 8;
  const specs = roundSpecs(playerCount);
  const expectedCodes = specs.reduce((total, spec) => total + spec.matchCount, 0);
  if (boardCodes.length !== expectedCodes || new Set(boardCodes).size !== boardCodes.length)
    throw new Error('Tournament deals must be unique.');
  let codeIndex = 0;
  const rounds = specs.map((spec, roundIndex) => {
    const matches = Array.from({ length: spec.matchCount }, (_, matchIndex) => {
      const code = boardCodes[codeIndex++];
      const parsed = code === undefined ? null : parseBoardCode(code);
      if (!code || !parsed || parsed.size !== spec.size) throw new Error('Invalid tournament deal.');
      const players: readonly [number | null, number | null] =
        roundIndex === 0 ? MATCHUPS[playerCount][matchIndex] ?? [null, null] : [null, null];
      return emptyMatch(code, players);
    });
    return { name: spec.name, size: spec.size, matches };
  });
  const players = names.map((name, index) => ({ seed: index + 1, name }));
  const firstMatch = rounds[0]?.matches[0];
  if (!firstMatch) throw new Error('Invalid tournament bracket.');
  return {
    startedAtMs,
    completedAtMs: null,
    players,
    rounds,
    currentRound: 0,
    currentMatch: 0,
    currentTurn: 0,
    phase: 'ready',
    championSeed: null,
    game: createGame(firstMatch.boardCode),
    generation: 0,
    paused: true,
  };
}
import { encodeSnapshot } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { readActiveTournament } from './active-validation.ts';
import { restoreTournamentRecord, tournamentRecord } from './records.ts';
import { readTournamentRecord } from './validation.ts';
import type { TournamentRecord, TournamentState } from './model.ts';

const TOURNAMENT_VERSION = 1;
const TOURNAMENT_MAX_BYTES = 262_144;

interface TournamentSetupDraft {
  readonly playerCount: 4 | 8;
  readonly names: readonly string[];
}

type LoadedTournament =
  | { readonly kind: 'setup'; readonly draft: TournamentSetupDraft }
  | { readonly kind: 'active'; readonly tournament: TournamentState }
  | { readonly kind: 'finished'; readonly tournament: TournamentState; readonly record: TournamentRecord };

export function encodeTournamentDraft(draft: TournamentSetupDraft): string {
  return JSON.stringify(
    {
      version: TOURNAMENT_VERSION,
      status: 'setup',
      playerCount: draft.playerCount,
      names: draft.names,
    },
    null,
    2,
  );
}

export function encodeTournament(tournament: TournamentState): string {
  if (tournament.phase === 'finished') {
    return JSON.stringify(
      { version: TOURNAMENT_VERSION, status: 'finished', record: tournamentRecord(tournament) },
      null,
      2,
    );
  }
  return JSON.stringify(
    {
      version: TOURNAMENT_VERSION,
      status: 'active',
      startedAtMs: tournament.startedAtMs,
      players: tournament.players,
      rounds: tournament.rounds,
      current: {
        roundIndex: tournament.currentRound,
        matchIndex: tournament.currentMatch,
        turnIndex: tournament.currentTurn,
        phase: tournament.phase,
      },
      gameSnapshot: encodeSnapshot(tournament.game),
    },
    null,
    2,
  );
}

function readSetup(value: Record<string, unknown>): TournamentSetupDraft | null {
  if (
    !hasExactKeys(value, ['version', 'status', 'playerCount', 'names']) ||
    value.version !== TOURNAMENT_VERSION ||
    value.status !== 'setup' ||
    (value.playerCount !== 4 && value.playerCount !== 8) ||
    !Array.isArray(value.names) ||
    value.names.length !== value.playerCount
  )
    return null;
  const names: string[] = [];
  for (const name of value.names) {
    if (typeof name !== 'string') return null;
    names.push(name);
  }
  return { playerCount: value.playerCount, names };
}

export function decodeTournament(text: string): LoadedTournament | null {
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (!isJsonObject(value) || value.version !== TOURNAMENT_VERSION || typeof value.status !== 'string')
    return null;
  if (value.status === 'setup') {
    const draft = readSetup(value);
    return draft ? { kind: 'setup', draft } : null;
  }
  if (value.status === 'active') {
    const tournament = readActiveTournament(value);
    return tournament ? { kind: 'active', tournament } : null;
  }
  if (
    value.status === 'finished' &&
    hasExactKeys(value, ['version', 'status', 'record'])
  ) {
    const record = readTournamentRecord(value.record);
    const tournament = record ? restoreTournamentRecord(record) : null;
    return record && tournament ? { kind: 'finished', tournament, record } : null;
  }
  return null;
}

import { expect, TestTimeouts, test } from './browser-test.ts';
import { generateBoard } from '../src/game/deck.ts';
import { isJsonObject } from '../src/game/saved-format.ts';
import type { Page } from '@playwright/test';

interface Pair {
  readonly first: number;
  readonly second: number;
}

function boardPairs(code: string): readonly Pair[] {
  const positions = new Map<number, number[]>();
  generateBoard(code).deck.forEach((face, index) => {
    const pair = positions.get(face) ?? [];
    pair.push(index);
    positions.set(face, pair);
  });
  return [...positions.values()].flatMap((indices) => {
    const first = indices[0];
    const second = indices[1];
    return first === undefined || second === undefined ? [] : [{ first, second }];
  });
}

async function playTurn(page: Page, code: string): Promise<void> {
  await page.getByRole('button', { name: 'Start turn', exact: true }).click();
  const cards = page.locator('.board .card');
  await expect(cards).toHaveCount(generateBoard(code).deck.length);
  for (const pair of boardPairs(code)) {
    await cards.nth(pair.first).click();
    await cards.nth(pair.second).click();
  }
  await expect(page.locator('.victory')).toContainText('Game complete in');
}

async function matchCode(
  page: Page,
  roundIndex: number,
  matchIndex: number,
): Promise<string> {
  const code = await page
    .locator('.tournament-round')
    .nth(roundIndex)
    .locator('tbody tr')
    .nth(matchIndex)
    .locator('.tournament-code')
    .textContent();
  if (!code) throw new Error('Tournament bracket did not show a deal code.');
  return code.trim();
}

test(
  'Tournament plays a knockout, exchanges JSON and retains the finished bracket after reload',
  async ({ page, gameURL }) => {
    await page.goto(gameURL);
    await page.getByRole('button', { name: 'Tournament', exact: true }).click();
    await expect(page.getByRole('heading', { name: 'Tournament', exact: true })).toBeFocused();
    const players = page.getByLabel('Players', { exact: true });
    await players.selectOption('8');
    await expect(page.getByLabel('Player 8', { exact: true })).toBeVisible();
    await players.selectOption('4');
    for (const [index, name] of ['Ada', 'Bo', 'Cora', 'Dev'].entries())
      await page.getByLabel(`Player ${index + 1}`, { exact: true }).fill(name);
    await page.getByRole('button', { name: 'Start tournament', exact: true }).click();
    await expect(page.locator('.tournament-current-player')).toHaveText('Now playing: Ada');

    const tournamentJson = page.getByLabel('Tournament JSON', { exact: true });
    const exportButton = page.getByRole('button', { name: 'Export tournament', exact: true });
    await exportButton.click();
    const activeText = await tournamentJson.inputValue();
    const activeValue: unknown = JSON.parse(activeText);
    expect(isJsonObject(activeValue) && activeValue.status).toBe('active');
    await page.getByRole('button', { name: 'Load tournament', exact: true }).click();
    await expect(page.locator('.tournament-current-player')).toHaveText('Now playing: Ada');

    const firstDeal = await matchCode(page, 0, 0);
    await playTurn(page, firstDeal);
    await page.getByRole('button', { name: 'Next turn', exact: true }).click();
    await expect(page.locator('.tournament-current-player')).toHaveText('Now playing: Dev');
    expect(await matchCode(page, 0, 0)).toBe(firstDeal);
    await playTurn(page, firstDeal);
    await page.getByRole('button', { name: 'Next match', exact: true }).click();

    const secondDeal = await matchCode(page, 0, 1);
    await expect(page.locator('.tournament-current-player')).toHaveText('Now playing: Bo');
    await playTurn(page, secondDeal);
    await page.getByRole('button', { name: 'Next turn', exact: true }).click();
    await expect(page.locator('.tournament-current-player')).toHaveText('Now playing: Cora');
    expect(await matchCode(page, 0, 1)).toBe(secondDeal);
    await playTurn(page, secondDeal);
    await page.getByRole('button', { name: 'Next match', exact: true }).click();

