import { formatElapsed } from '../elapsed-time.ts';
import type { TournamentPlayer, TournamentResult, TournamentRound } from './model.ts';
import './tournament.css';

interface BracketProps {
  players: readonly TournamentPlayer[];
  rounds: readonly TournamentRound[];
}

function displayResult(
  seed: number | null,
  result: TournamentResult | null,
  players: readonly TournamentPlayer[],
): string {
  if (seed === null) return 'TBD';
  const player = players.find((candidate) => candidate.seed === seed);
  if (!player) return 'TBD';
  const score = result
    ? `${result.moves} moves · ${formatElapsed(result.elapsedMs)}`
    : 'Not played';
  return `${player.name} — ${score}`;
}

function playerName(seed: number | null, players: readonly TournamentPlayer[]): string {
  return players.find((player) => player.seed === seed)?.name ?? 'Pending';
}

export function Bracket({ players, rounds }: BracketProps) {
  return (
    <div className="tournament-bracket">
      {rounds.map((round) => (
        <section
          className="tournament-round"
          key={round.name}
          aria-labelledby={`round-${round.name}`}
        >
          <h3 id={`round-${round.name}`}>Round: {round.name}</h3>
          <div className="tournament-table-scroll">
            <table>
              <caption>{round.name} matches</caption>
              <thead>
                <tr>
                  <th scope="col">Match</th>
                  <th scope="col">Player 1</th>
                  <th scope="col">Player 2</th>
                  <th scope="col">Winner</th>
                </tr>
              </thead>
              <tbody>
                {round.matches.map((match, index) => (
                  <tr key={match.boardCode}>
                    <th scope="row">
                      Match {index + 1}
                      <span className="tournament-code">{match.boardCode}</span>
                    </th>
                    <td>{displayResult(match.players[0], match.results[0], players)}</td>
                    <td>{displayResult(match.players[1], match.results[1], players)}</td>
                    <td>{playerName(match.winnerSeed, players)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      ))}
    </div>
  );
}
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import type { PreferenceStore } from '../session/storage.ts';
import type { TournamentRecord } from './model.ts';
import { readTournamentRecord } from './validation.ts';

const TOURNAMENTS_KEY = 'neon-pairs.tournaments.v1';
const STORAGE_VERSION = 3;
const PAST_TOURNAMENT_LIMIT = 10;
const STORAGE_MAX_BYTES = 262_144;

function recordKey(record: TournamentRecord): string {
  const firstCode = record.rounds[0]?.matches[0]?.boardCode ?? '';
  return `${record.startedAtMs}:${firstCode}`;
}

export function readPastTournaments(store: PreferenceStore | null): readonly TournamentRecord[] {
  try {
    const text = store?.getItem(TOURNAMENTS_KEY);
    if (!text || !isWithinBytes(text, STORAGE_MAX_BYTES)) return [];
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      !hasExactKeys(value, ['v', 'items']) ||
      value.v !== STORAGE_VERSION ||
      !Array.isArray(value.items) ||
      value.items.length > PAST_TOURNAMENT_LIMIT
    )
      return [];
    const records: TournamentRecord[] = [];
    for (const item of value.items) {
      const record = readTournamentRecord(item);
      if (!record) return [];
      records.push(record);
    }
    return records;
  } catch {
    return [];
  }
}

export function prependPastTournament(
  records: readonly TournamentRecord[],
  record: TournamentRecord,
): readonly TournamentRecord[] {
  const key = recordKey(record);
  return [record, ...records.filter((item) => recordKey(item) !== key)].slice(
    0,
    PAST_TOURNAMENT_LIMIT,
  );
}

export function hasSavedPastTournaments(
  store: PreferenceStore | null,
  records: readonly TournamentRecord[],
): boolean {
  try {
    store?.setItem(
      TOURNAMENTS_KEY,
      JSON.stringify({ v: STORAGE_VERSION, items: records.slice(0, PAST_TOURNAMENT_LIMIT) }),
    );
    return store !== null;
  } catch {
    return false;
  }
}
import { createGame } from '../game.ts';
import type { TournamentRecord, TournamentState } from './model.ts';

export function tournamentRecord(tournament: TournamentState): TournamentRecord {
  if (
    tournament.phase !== 'finished' ||
    tournament.championSeed === null ||
    tournament.completedAtMs === null
  )
    throw new Error('Tournament is not complete.');
  return {
    startedAtMs: tournament.startedAtMs,
    completedAtMs: tournament.completedAtMs,
    players: tournament.players,
    rounds: tournament.rounds,
    championSeed: tournament.championSeed,
  };
}

export function restoreTournamentRecord(record: TournamentRecord): TournamentState {
  const currentRound = record.rounds.length - 1;
  const currentMatch = (record.rounds[currentRound]?.matches.length ?? 1) - 1;
  const finalMatch = record.rounds[currentRound]?.matches[currentMatch];
  if (!finalMatch) throw new Error('Invalid tournament record.');
  return {
    startedAtMs: record.startedAtMs,
    completedAtMs: record.completedAtMs,
    players: record.players,
    rounds: record.rounds,
    currentRound,
    currentMatch,
    currentTurn: 1,
    phase: 'finished',
    championSeed: record.championSeed,
    game: createGame(finalMatch.boardCode),
    generation: 0,
    paused: true,
  };
}

import { expect, TestTimeouts, test } from './browser-test.ts';
import { generateBoard } from '../src/game/deck.ts';
import { isJsonObject } from '../src/game/saved-format.ts';
import type { Page } from '@playwright/test';

interface Pair {
  readonly first: number;
  readonly second: number;
}

function boardPairs(code: string): readonly Pair[] {
  const positions = new Map<number, number[]>();
  generateBoard(code).deck.forEach((face, index) => {
    const pair = positions.get(face) ?? [];
    pair.push(index);
    positions.set(face, pair);
  });
  return [...positions.values()].flatMap((indices) => {
    const first = indices[0];
    const second = indices[1];
    return first === undefined || second === undefined ? [] : [{ first, second }];
  });
}

async function playTurn(page: Page, code: string): Promise<void> {
  await page.getByRole('button', { name: 'Start turn', exact: true }).click();
  const cards = page.locator('.board .card');
  await expect(cards).toHaveCount(generateBoard(code).deck.length);
  for (const pair of boardPairs(code)) {
    await cards.nth(pair.first).click();
    await cards.nth(pair.second).click();
  }
  await expect(page.locator('.victory')).toContainText('Game complete in');
}

async function matchCode(page: Page, roundIndex: number, matchIndex: number): Promise<string> {
  const code = await page
    .locator('.tournament-round')
    .nth(roundIndex)
    .locator('tbody tr')
    .nth(matchIndex)
    .locator('.tournament-code')
    .textContent();
  if (!code) throw new Error('Tournament bracket did not show a deal code.');
  return code.trim();
}

